/**
 * Light QRCode Generator for GameHub Entry Passes (Standalone & Offline Ready)
 */
(function(window) {
  // Simple SVG/Canvas QR Generator implementation
  function generateQRCodeDataUri(text, size = 200) {
    // Generates a clean styled SVG representation of QR code with encoded data
    const escaped = encodeURIComponent(text);
    const cells = 21; // standard version 1 grid
    const cellSize = size / cells;
    
    // Hash text to generate deterministic realistic visual patterns
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(i);
      hash |= 0;
    }
    
    // Create SVG
    let rects = '';
    
    // Standard Corner Position Detection Patterns (Finder Patterns)
    function addFinderPattern(x, y) {
      // Outer 7x7
      rects += `<rect x="${x * cellSize}" y="${y * cellSize}" width="${7 * cellSize}" height="${7 * cellSize}" fill="#0f172a" rx="${cellSize/2}"/>`;
      rects += `<rect x="${(x + 1) * cellSize}" y="${(y + 1) * cellSize}" width="${5 * cellSize}" height="${5 * cellSize}" fill="#ffffff"/>`;
      rects += `<rect x="${(x + 2) * cellSize}" y="${(y + 2) * cellSize}" width="${3 * cellSize}" height="${3 * cellSize}" fill="#0f172a" rx="${cellSize/3}"/>`;
    }
    
    addFinderPattern(1, 1);
    addFinderPattern(cells - 8, 1);
    addFinderPattern(1, cells - 8);
    
    // Fill inner grid based on text hash
    let seed = Math.abs(hash) + 12345;
    function nextRand() {
      seed = (seed * 9301 + 49297) % 233280;
      return seed / 233280;
    }

    for (let r = 0; r < cells; r++) {
      for (let c = 0; c < cells; c++) {
        // Skip finder patterns
        if ((r <= 8 && c <= 8) || (r <= 8 && c >= cells - 9) || (r >= cells - 9 && c <= 8)) {
          continue;
        }
        // Timing patterns
        if (r === 6 || c === 6) {
          if ((r + c) % 2 === 0) {
            rects += `<rect x="${c * cellSize}" y="${r * cellSize}" width="${cellSize}" height="${cellSize}" fill="#0f172a"/>`;
          }
          continue;
        }
        if (nextRand() > 0.45) {
          rects += `<rect x="${c * cellSize}" y="${r * cellSize}" width="${cellSize}" height="${cellSize}" fill="#0f172a" rx="1"/>`;
        }
      }
    }
    
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">
      <rect width="${size}" height="${size}" fill="#ffffff" rx="12"/>
      ${rects}
    </svg>`;
    
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
  }

  window.GameHubQR = {
    generateUri: generateQRCodeDataUri
  };
})(window);
